// Bad: duplicated
function firstString(arr: string[]): string { return arr[0]; }
function firstNumber(arr: number[]): number { return arr[0]; }

// Bad: unchecked
function firstAny(arr: any[]): any { return arr[0]; }

// Good: generic (next screen)

function first<T>(arr: T[]): T {
  return arr[0];
}

const s: string = first(["a", "b"]); // T is string
const n: number = first([1, 2]);       // T is number
// const x: number = first(["a"]);    // ERROR: it's a string!

interface Box<T> {
  value: T;
}

const nameBox: Box<string> = { value: "Roli" };
const ageBox: Box<number> = { value: 19 };

// You've used generics all along:
const list: Array<string> = ["a", "b"];

function longest<T extends { length: number }>(
  a: T,
  b: T
): T {
  return a.length >= b.length ? a : b;
}

longest("hello", "hi"); // fine — strings have length
longest([1, 2], [3]);     // fine — arrays have length
// longest(5, 10);         // ERROR: numbers don't

function pair<K, V>(key: K, value: V): [K, V] {
  return [key, value];
}

const p: [string, number] = pair("age", 19);

const scores = new Map<string, number>();
scores.set("Roli", 98);

// display-only
async function fetchData<T>(url: string): Promise<T> {
  const res = await fetch(url);
  return res.json();
}

const me = await fetchData<User>("/api/me");
// me is typed User — me.name autocompletes!

// Don't do this:
function echoString(x: string): string { return x; }
function echoNumber(x: number): number { return x; }

// Do this:
function echo<T>(x: T): T { return x; }
